def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = {}
    undo_stack = []
    rejected = []

    def valid_amount(tok):
        return tok.isdigit() and tok != ""

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""

        if verb == "undo":
            if len(parts) != 1 or not undo_stack:
                rejected.append(i)
            else:
                rec = undo_stack.pop()
                kind = rec[0]
                if kind == "open":
                    balances.pop(rec[1], None)
                    frozen.pop(rec[1], None)
                elif kind == "dep":
                    balances[rec[1]] -= rec[2]
                elif kind == "wd":
                    balances[rec[1]] += rec[2]
                elif kind == "tr":
                    balances[rec[1]] += rec[3]
                    balances[rec[2]] -= rec[3]
                elif kind == "freeze":
                    frozen[rec[1]] = False
                elif kind == "unfreeze":
                    frozen[rec[1]] = True
            continue

        if verb == "open":
            if len(parts) != 3 or not valid_amount(parts[2]) or parts[1] in balances:
                rejected.append(i)
                continue
            n = int(parts[2])
            if n < 0:  # unreachable: digits only, but keep spec-safe
                rejected.append(i)
                continue
            balances[parts[1]] = n
            frozen[parts[1]] = False
            undo_stack.append(("open", parts[1]))
        elif verb == "deposit":
            if len(parts) != 3 or not valid_amount(parts[2]) or parts[1] not in balances:
                rejected.append(i)
                continue
            n = int(parts[2])
            if n <= 0:
                rejected.append(i)
                continue
            balances[parts[1]] += n
            undo_stack.append(("dep", parts[1], n))
        elif verb == "withdraw":
            if len(parts) != 3 or not valid_amount(parts[2]) or parts[1] not in balances:
                rejected.append(i)
                continue
            n = int(parts[2])
            if n <= 0 or frozen[parts[1]] or balances[parts[1]] < n:
                rejected.append(i)
                continue
            balances[parts[1]] -= n
            undo_stack.append(("wd", parts[1], n))
        elif verb == "transfer":
            if len(parts) != 4 or not valid_amount(parts[3]):
                rejected.append(i)
                continue
            a, b, n = parts[1], parts[2], int(parts[3])
            if (n <= 0 or a == b or a not in balances or b not in balances
                    or frozen[a] or balances[a] < n):
                rejected.append(i)
                continue
            balances[a] -= n
            balances[b] += n
            undo_stack.append(("tr", a, b, n))
        elif verb == "freeze":
            if len(parts) != 2 or parts[1] not in balances or frozen[parts[1]]:
                rejected.append(i)
                continue
            frozen[parts[1]] = True
            undo_stack.append(("freeze", parts[1]))
        elif verb == "unfreeze":
            if len(parts) != 2 or parts[1] not in balances or not frozen[parts[1]]:
                rejected.append(i)
                continue
            frozen[parts[1]] = False
            undo_stack.append(("unfreeze", parts[1]))
        else:
            rejected.append(i)

    return balances, rejected
